import { describe, expect, it } from "vitest";
import { lookupMacs, analyzeMac, nvdSearchUrl, type OuiData } from "./logic";

// Hand-built fixture — the real registry is generated by scripts/update-oui.mjs.
const DATA: OuiData = {
  count: 3,
  prefixes: {
    "0050c2": "Generic MA-L Vendor",
    "0050c2a": "MA-M Sub Vendor", // 28-bit
    "0050c2ab0": "MA-S Tiny Vendor", // 36-bit
    "001122": "Acme Networks",
  },
};

describe("analyzeMac", () => {
  it("resolves a registered MA-L vendor and reports a universal unicast address", () => {
    const r = analyzeMac("001122334455", "00:11:22:33:44:55", DATA);
    expect(r.vendor).toBe("Acme Networks");
    expect(r.oui).toBe("00:11:22");
    expect(r.mac).toBe("00:11:22:33:44:55");
    expect(r.local).toBe(false);
    expect(r.multicast).toBe(false);
  });

  it("prefers the most specific block (MA-S > MA-M > MA-L)", () => {
    expect(analyzeMac("0050c2ab0111", "x", DATA).vendor).toBe("MA-S Tiny Vendor");
    expect(analyzeMac("0050c2a11111", "x", DATA).vendor).toBe("MA-M Sub Vendor");
    expect(analyzeMac("0050c211111 1".replace(" ", ""), "x", DATA).vendor).toBe(
      "Generic MA-L Vendor",
    );
  });

  it("flags a locally-administered MAC with no vendor as randomized/private", () => {
    const r = analyzeMac("0211223344 55".replace(" ", ""), "02:11:22:33:44:55", DATA);
    expect(r.local).toBe(true);
    expect(r.vendor).toBe(null);
    expect(r.note).toMatch(/randomized|private/i);
  });

  it("decodes the multicast (I/G) bit", () => {
    const r = analyzeMac("01005e0000fb", "01:00:5e:00:00:fb", DATA);
    expect(r.multicast).toBe(true);
  });

  it("recognizes the broadcast address", () => {
    const r = analyzeMac("ffffffffffff", "ff:ff:ff:ff:ff:ff", DATA);
    expect(r.broadcast).toBe(true);
    expect(r.note).toMatch(/broadcast/i);
  });
});

describe("lookupMacs", () => {
  it("returns nothing for blank input", () => {
    expect(lookupMacs("   ", DATA).entries).toEqual([]);
  });

  it("extracts MACs in colon, hyphen, Cisco and bare forms", () => {
    const text = `
      00:11:22:33:44:55
      00-11-22-33-44-66
      0011.2233.4477
      001122334488
    `;
    const macs = lookupMacs(text, DATA).entries.map((e) => e.mac);
    expect(macs).toEqual([
      "00:11:22:33:44:55",
      "00:11:22:33:44:66",
      "00:11:22:33:44:77",
      "00:11:22:33:44:88",
    ]);
  });

  it("pulls a MAC out of surrounding text (arp-style) and dedupes", () => {
    const text =
      "? (192.168.1.1) at 00:11:22:33:44:55 [ether] on eth0\n" +
      "? (192.168.1.2) at 00:11:22:33:44:55 [ether] on eth0";
    const r = lookupMacs(text, DATA);
    expect(r.entries).toHaveLength(1);
    expect(r.entries[0].vendor).toBe("Acme Networks");
  });

  it("does not match a 12-hex slice inside a longer hash", () => {
    // 64-hex SHA-256-looking string — no MAC should be pulled out of the middle.
    const sha = "a".repeat(64);
    expect(lookupMacs(sha, DATA).entries).toEqual([]);
  });
});

describe("lookupMacs — malformed detection", () => {
  it("flags a colon/hyphen MAC with the wrong number of octets", () => {
    const r = lookupMacs("00:11:22:33:44\nAA-BB-CC", DATA); // 5 and 3 groups
    expect(r.entries).toEqual([]);
    expect(r.malformed).toEqual(["00:11:22:33:44", "AA-BB-CC"]);
  });

  it("flags a too-short Cisco-format token", () => {
    expect(lookupMacs("0011.2233", DATA).malformed).toEqual(["0011.2233"]);
  });

  it("strips wrapping punctuation before judging", () => {
    expect(lookupMacs("(aa:bb:cc:dd)", DATA).malformed).toEqual(["aa:bb:cc:dd"]);
  });

  it("leaves valid MACs, IPs and ordinary words alone", () => {
    const r = lookupMacs("? (10.14.0.7) at 00:11:22:33:44:55 [ether] on eth0", DATA);
    expect(r.entries).toHaveLength(1);
    expect(r.entries[0].vendor).toBe("Acme Networks");
    expect(r.malformed).toEqual([]); // the IP and words are not MAC-shaped
  });

  it("does not double-flag a valid MAC as malformed", () => {
    const r = lookupMacs("00:11:22:33:44:55", DATA);
    expect(r.entries).toHaveLength(1);
    expect(r.malformed).toEqual([]);
  });
});

describe("nvdSearchUrl", () => {
  it("points at the NVD keyword search", () => {
    expect(nvdSearchUrl("Cisco Systems")).toMatch(/^https:\/\/nvd\.nist\.gov\/vuln\/search/);
  });

  it("trims corporate suffixes for a cleaner query", () => {
    const q = decodeURIComponent(nvdSearchUrl("Apple, Inc."));
    expect(q).toContain("Apple");
    expect(q).not.toMatch(/\bInc\b/);
  });

  it("keeps a bare vendor name intact", () => {
    expect(decodeURIComponent(nvdSearchUrl("Espressif"))).toContain("Espressif");
  });

  it("falls back to the full name when trimming would empty it", () => {
    // A name that is *only* a suffix word must still produce a usable query.
    expect(decodeURIComponent(nvdSearchUrl("Limited"))).toContain("Limited");
  });
});
